if(a==='add-supplier'){supplierForm();return}if(a==='edit-supplier'){supplierForm(data.suppliers.find(s=>s.id===k));return}
if(a==='save-supplier'){const total=val('total'),existing=data.suppliers.find(s=>s.id===k);if(!val('supplierName').trim())return error('Enter the supplier’s name.');if(existing&&paidFor(existing)>0&&!checked('booked'))return error('A booking with recorded payments must stay confirmed.');if(total!==''&&!finiteAmount(total))return error('Enter a valid price or leave it blank.');if(existing&&((total===''&&paidFor(existing)>0)||(total!==''&&Number(total)<Math.max(paidFor(existing),scheduledFor(existing)))))return error('The total cannot be below your payment schedule. Edit the instalments first.');mutate(()=>upsert(data.suppliers,{id:k||id(),name:val('supplierName').trim(),category:val('category').trim()||'Other',total:total===''?null:Number(total),booked:checked('booked'),contact:val('contact').trim(),finish:minutes(val('finish'))}),'Booking saved. Budget and payment links updated.');return}
