if(a==='save-guest'){if(!val('guestName').trim())return error('Enter this guest’s name.');const g={id:k||id(),name:val('guestName').trim(),household:val('household').trim(),attendance:val('attendance'),rsvp:val('rsvp'),meal:val('meal').trim(),diet:val('diet').trim(),access:val('access').trim(),table:val('table').trim()};mutate(()=>upsert(data.guests,g),'Guest saved individually.');return}
